```java
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.*;

public class AirportSimulation {
    static final Semaphore runway = new Semaphore(1, true);
    static final Semaphore airportCapacity = new Semaphore(3, true);
    static final Semaphore gates = new Semaphore(2, true);
    static final Semaphore fuelTruck = new Semaphore(1, true);
    static final AtomicInteger planesServed = new AtomicInteger(0);
    static final AtomicInteger totalPassengers = new AtomicInteger(0);
    static final List<Long> waitTimes = Collections.synchronizedList(new ArrayList<>());

    static class Plane extends Thread {
        int id; boolean emergency; long arrivalTime;
        Plane(int id, boolean emergency) {
            super("Thread-Plane-" + id);
            this.id = id; this.emergency = emergency;
            if (emergency) setPriority(Thread.MAX_PRIORITY);
        }
        public void run() {
            arrivalTime = System.currentTimeMillis();
            try {
                System.out.println(getName() + ": Requesting landing" + (emergency ? " [EMERGENCY: LOW FUEL]!" : "."));
                airportCapacity.acquire();
                runway.acquire();
                long wait = System.currentTimeMillis() - arrivalTime;
                waitTimes.add(wait);
                System.out.println(getName() + ": Landed on runway. Wait time: " + wait + "ms");
                Thread.sleep(100);
                gates.acquire();
                runway.release();
                System.out.println(getName() + ": Docked at gate.");
                Thread disembark = new Thread(() -> System.out.println("Thread-Passenger: Disembarking from " + getName()));
                disembark.start();
                fuelTruck.acquire();
                System.out.println(getName() + ": Refueling exclusively by truck.");
                Thread.sleep(150);
                fuelTruck.release();
                disembark.join();
                int passengers = 50;
                totalPassengers.addAndGet(passengers);
                System.out.println("Thread-Passenger: Boarded " + passengers + " passengers onto " + getName());
                runway.acquire();
                gates.release();
                System.out.println(getName() + ": Undocked, taking off on runway.");
                Thread.sleep(100);
                runway.release();
                airportCapacity.release();
                planesServed.incrementAndGet();
                System.out.println(getName() + ": Departed safely.");
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("Thread-ATC: Simulation started. Monitoring 6 planes.");
        List<Plane> planes = new ArrayList<>();
        for (int i = 1; i <= 6; i++) {
            boolean em = (i == 3);
            Plane p = new Plane(i, em);
            planes.add(p);
            p.start();
            Thread.sleep(new Random().nextInt(300));
        }
        for (Plane p : planes) p.join();
        System.out.println("Thread-ATC: Sanity Check - All gates empty (" + (gates.availablePermits() == 2) + ")");
        long maxW = waitTimes.stream().mapToLong(v -> v).max().orElse(0);
        long minW = waitTimes.stream().mapToLong(v -> v).min().orElse(0);
        double avgW = waitTimes.stream().mapToLong(v -> v).average().orElse(0);
        System.out.printf("Thread-ATC: Stats - Planes Served: %d, Passengers: %d, Min Wait: %dms, Max Wait: %dms, Avg Wait: %.2fms%n",
            planesServed.get(), totalPassengers.get(), minW, maxW, avgW);
    }
}
```

